// CONFIDENCE: MEDIUM. Native body.
// Gate 1: the world's zone object at World+0x130 must be a UFortGameStateZone (IsA check via the class chain), else Zone = null.
UFortGameStateZone* Zone = IsA<UFortGameStateZone>(World->Zone130) ? World->Zone130 : nullptr;
if (Role != ROLE_Authority) return;
if (Zone == nullptr) return;

const float Rad = ZAngleDeg * (PI / 180.0f);
const float CosA = cosf(Rad);
const float SinA = sinf(Rad);

// Normalise the XY part of the direction. Degenerate (|xy|^2 < 1e-8) gives zero XY.
FVector2D Dir2 = FVector2D(ImpulseDir->X, ImpulseDir->Y);
float LenSq = Dir2.X * Dir2.X + Dir2.Y * Dir2.Y;
if (LenSq == 1.0f) { if (ImpulseDir->Z == 0.0f) { /* already unit */ } }
else if (LenSq < 1e-8f) { Dir2 = FVector2D::ZeroVector; }
else { Dir2 /= sqrtf(LenSq); }

const float Vertical = SinA * KnockbackMagnitude;
const FVector KnockVel(CosA * Dir2.X * KnockbackMagnitude, CosA * Dir2.Y * KnockbackMagnitude, Vertical);

UFortMovementComp_Character* Movement = GetMovementComponent();
if (Movement != nullptr && Movement->IsA(UFortMovementComp_Character::StaticClass()) && Vertical > 0.0f)
{
    Movement->SetFlag124(false);   // original clears bit 0x8 of the byte at +0x124 (name unknown)
    Movement->ClearAccumulatedState();   // vslot 0x420 (UCharacterMovementComponent, LOW name)
    Movement->SetFlag124(true);
    Movement->SetMovementMode(MOVE_Falling);   // vslot 0x590 with argument 3 (LOW name)
    Movement->Velocity = KnockVel;   // raw +0xc4 (x,y), +0xcc (z)
    ForceNetUpdate();                // vslot 0x5e8
}
